lor:#667085;font-size:13px"><b style="color:#17233c">Delivery to:</b><br><?php echo e($order->shipping_address); ?><br><br>Payment: <?php echo e($order->payment_method); ?></p></td></tr><tr><td style="padding:18px 36px;background:#f8fafc;color:#8490a2;text-align:center;font-size:12px">Questions? Reply to this email and we’ll be happy to help.</td></tr></table></td></tr></table></body></html>
